// Copies the map kit (src/maps/kit/: model, stamps, renderer, random maps) into
// supabase/functions/_shared/maps/, so the Edge Functions (which can only bundle files under
// supabase/functions/) draw maps exactly like the app. Run with `pnpm maps:bundle` after editing the
// kit. A unit test (src/maps/kit/kit.test.ts) fails if the copy is stale.
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'

export const KIT_DIR = 'src/maps/kit'
export const BUNDLE_DIR = 'supabase/functions/_shared/maps'

/** The kit's files (tests left out), as they must be in the functions' copy. */
export function buildMapBundle() {
  return readdirSync(KIT_DIR)
    .filter((f) => f.endsWith('.ts') && !f.endsWith('.test.ts'))
    .sort()
    .map((name) => ({ name, text: `// Generated by scripts/gen-map-bundle.mjs from ${KIT_DIR}/${name}. Do not edit.\n${readFileSync(`${KIT_DIR}/${name}`, 'utf8')}` }))
}

if (process.argv[1]?.endsWith('gen-map-bundle.mjs')) {
  mkdirSync(BUNDLE_DIR, { recursive: true })
  for (const { name, text } of buildMapBundle()) writeFileSync(`${BUNDLE_DIR}/${name}`, text)
  console.log(`map kit copied to ${BUNDLE_DIR}`)
}
